// 154 KiB of real minified JS. Tiled rather than repeated at a small period: gzip has a 32 KiB
// window, so a repeat this far apart does not compress, and the ratio stays realistic. The old
// origin tiled a 150-byte fragment and hit 220:1, which erased the per-wire-byte cost entirely.
export const CORPUS = Uint8Array.from(atob(""),ch=>ch.charCodeAt(0));
